<template>
  <view class="page-shell gate-page">
    <view class="gate-hero"><text class="gate-eyebrow">HUFE · IDENTITY CHECK</text><text class="gate-title">平台返校身份核验</text><text class="gate-description">授权人员工作台 · 扫码、核对、确认、留存记录</text><text class="gate-policy">请现场核对本人身份，填写说明并明确确认后保存核验记录。</text></view>
    <view v-if="error" class="gate-error" role="alert">{{ error }}</view><view v-if="notice" class="gate-notice" role="status">{{ notice }}</view>
    <view v-if="loading && !role" class="surface gate-box">正在核对工作权限…</view>
    <view v-else-if="!role?.canScan" class="surface gate-box"><text class="gate-heading">{{ ownerToken ? '尚未获得核验权限' : '请先登录核验人员账号' }}</text><text class="gate-muted">后台管理员可授权保卫负责人；负责人可分配保安。普通实名用户请在“我的湖财身份卡”出示动态码。</text><button class="primary-button" @tap="open('/pages/verify/index')">前往账号登录</button><button class="secondary-button" @tap="load">重新检查权限</button></view>
    <template v-else>
      <view class="gate-tabs"><button :class="{active:tab==='scan'}" @tap="switchTab('scan')">身份核验</button><button :class="{active:tab==='records'}" @tap="switchTab('records')">核验记录</button><button v-if="role.canManage" :class="{active:tab==='manage'}" @tap="switchTab('manage')">人员与站点</button></view>
      <view v-if="tab==='scan'" class="surface gate-box">
        <text class="gate-heading">1. 选择核验站点</text><picker :range="activeStations" range-key="name" :value="stationIndex" :disabled="busy || cameraActive" @change="selectStation"><view class="gate-select">{{ activeStations[stationIndex]?.name || '暂无启用站点，请联系负责人配置' }} <text>⌄</text></view></picker>
        <template v-if="!preview">
          <text class="gate-heading gate-spaced">2. 读取本人动态二维码</text><text class="gate-muted">现场扫码或识别图片均在本机完成；未确认前不会记录放行。</text>
          <view ref="cameraBox" class="gate-camera" v-show="cameraActive"></view>
          <button v-if="cameraActive" class="secondary-button" @tap="stopCamera">关闭相机</button>
          <view v-else class="gate-actions"><button class="primary-button" :disabled="busy || !activeStations[stationIndex]" @tap="startCamera">开启相机扫码</button><button class="secondary-button" :disabled="busy || !activeStations[stationIndex]" @tap="chooseImage">识别二维码图片</button></view>
          <view class="gate-manual"><text class="gate-muted">备用：粘贴身份卡复制的临时核验码（不是扫码）</text><textarea v-model="manualCode" class="gate-input gate-code-input" maxlength="230" placeholder="HUFE-GATE-V1:…" :disabled="busy"/><button class="secondary-button" :disabled="busy || !manualCode.trim() || !activeStations[stationIndex]" @tap="inspect(manualCode,'手动核验码')">读取临时码</button></view>
        </template>
        <view v-else class="gate-preview">
          <text class="gate-heading">3. 核对人员并明确确认</text><text class="gate-muted">来源：{{ previewSource }} · 待核验有效 {{ previewRemaining }} 秒</text>
          <view class="gate-person"><text class="gate-person-name">{{ preview.person.name }}</text><text>{{ typeLabel(preview.person.personType) }} · {{ preview.person.department || '未提供学院 / 部门' }}</text><text v-if="preview.person.studentIdMasked">学工号：{{ preview.person.studentIdMasked }}</text><text v-if="preview.person.alumniNo">校友编号：{{ preview.person.alumniNo }}</text><text>站点：{{ preview.station.name }}</text></view>
          <text class="gate-muted">请现场核对本人，不要仅凭他人转发图片放行。</text><textarea v-model="reason" class="gate-input" maxlength="300" placeholder="核验说明（必填），例如：已现场核对本人身份" :disabled="busy"/>
          <view class="gate-actions"><button class="primary-button" :disabled="busy || !reason.trim() || !previewRemaining" @tap="confirm('allow')">核对无误，确认放行</button><button class="gate-deny" :disabled="busy || !reason.trim() || !previewRemaining" @tap="confirm('deny')">不予放行</button></view><button class="gate-link" :disabled="busy" @tap="clearPreview">取消本次核验</button>
        </view>
      </view>
      <view v-if="tab==='records'" class="surface gate-box"><view class="gate-section-head"><text class="gate-heading">{{ role.canManage ? '核验记录' : '我办理的核验记录' }}</text><button class="gate-link" :disabled="busy" @tap="loadRecords">刷新</button></view><text class="gate-muted">仅已明确确认的放行或拒绝操作才会生成记录。</text><view v-for="row in records" :key="row.id" class="gate-list-row"><view><text class="gate-row-title">{{ row.person?.name || row.personName || '身份核验' }} · {{ row.decision==='allow'?'已放行':'未放行' }}</text><text class="gate-muted">{{ row.station?.name || row.stationName }} · {{ dateText(row.createdAt) }}</text><text class="gate-muted">{{ row.reason }}</text><text v-if="row.operator?.name || row.operatorName" class="gate-muted">核验人：{{ row.operator?.name || row.operatorName }}</text></view></view><text v-if="!records.length" class="gate-muted">暂无已确认记录</text><view class="gate-pagination"><button :disabled="page<=1 || busy" @tap="page--;loadRecords()">上一页</button><text>{{ page }} / {{ Math.max(1,Math.ceil(total/20)) }}</text><button :disabled="page*20>=total || busy" @tap="page++;loadRecords()">下一页</button></view></view>
      <template v-if="tab==='manage' && role.canManage">
        <view class="surface gate-box"><text class="gate-heading">授权现有人员</text><text class="gate-muted">新增账号请使用后台人员管理。这里分配核验工作权限；保安使用前台用户名和密码登录。</text><view class="gate-actions"><input v-model="peopleQuery" class="gate-input" maxlength="60" placeholder="搜索姓名或用户名" @confirm="searchPeople"/><button class="secondary-button" :disabled="busy" @tap="searchPeople">查询</button></view><view v-for="person in people" :key="person.id" class="gate-list-row"><view><text class="gate-row-title">{{ person.name || person.realName }} · {{ person.username }}</text></view><view class="gate-inline-actions"><button :disabled="busy" @tap="grant(person,'guard')">设为保安</button><button v-if="role.canGrantManagers" :disabled="busy" @tap="grant(person,'manager')">设为负责人</button></view></view><text class="gate-heading gate-spaced">已授权人员</text><view v-for="person in staff" :key="person.id" class="gate-list-row"><view><text class="gate-row-title">{{ person.person?.name || person.person?.username }} · {{ person.role==='manager'?'保卫负责人':'保安' }}</text><text class="gate-muted">{{ person.person?.username }} · {{ person.status==='active' && person.effective ? '权限有效' : '已失效' }}</text></view><button v-if="person.canRevoke && person.status==='active'" :disabled="busy" @tap="revoke(person)">撤销权限</button></view><text v-if="!staff.length" class="gate-muted">暂无授权人员</text></view>
        <view class="surface gate-box"><text class="gate-heading">核验站点</text><text class="gate-muted">停用后立即停止接收新核验，既有记录保留。</text><input v-model="stationName" class="gate-input" maxlength="80" placeholder="新站点名称"/><input v-model="stationDescription" class="gate-input" maxlength="300" placeholder="站点说明（选填）"/><button class="secondary-button" :disabled="busy || !stationName.trim()" @tap="addStation">新增核验站点</button><view v-for="station in stations" :key="station.id" class="gate-list-row"><view><text class="gate-row-title">{{ station.name }} · {{ station.status==='active'?'启用':'停用' }}</text><text class="gate-muted">{{ station.description }}</text></view><button :disabled="busy" @tap="toggleStation(station)">{{ station.status==='active'?'停用':'启用' }}</button></view></view>
      </template>
    </template>
    <SupportFooter />
  </view>
</template>

<script>
import { gateApi } from '../../services/gate'
import { loadAllPages } from '../../utils/pagination'
import { getAccessToken, identityLabel } from '../../utils/store'
import { openPage } from '../../utils/nav'
import { gateSeconds, normalizeGatePayload } from '../../utils/gateQr'
import { startGateCamera, pickGateQrImage } from '../../utils/gateScanner'

export default {
  data() { return { role:null,visible:false,generation:0,ownerToken:'',loading:false,busy:false,error:'',notice:'',tab:'scan',stations:[],stationIndex:0,preview:null,previewSource:'',reason:'',manualCode:'',cameraActive:false,stopCameraFn:null,records:[],total:0,page:1,staff:[],people:[],peopleQuery:'',stationName:'',stationDescription:'',now:Date.now(),timer:null,nextRoleCheck:0,roleChecking:false } },
  computed:{ activeStations(){return this.stations.filter(s=>s.status==='active')},previewRemaining(){return gateSeconds(this.preview?.expiresAt,this.now)} },
  onLoad(){uni.$on('hufe-auth-changed',this.load)},
  onShow(){this.visible=true;this.load();clearInterval(this.timer);this.timer=setInterval(()=>{this.now=Date.now();if(this.ownerToken!==getAccessToken()){this.load();return}if(this.preview&&!this.previewRemaining){this.clearPreview();this.error='待核验信息已过期，请重新扫码'}if(this.now>=this.nextRoleCheck&&!this.roleChecking)this.refreshRole()},1000)},
  onHide(){this.stop()},onUnload(){this.stop();uni.$off('hufe-auth-changed',this.load)},
  methods:{
    open:openPage,typeLabel:identityLabel,dateText(value){return value?new Date(value).toLocaleString('zh-CN'):'—'},
    current(g,token){return this.visible&&g===this.generation&&token===this.ownerToken&&token===getAccessToken()},
    clearPreview(){this.preview=null;this.previewSource='';this.reason='';this.manualCode=''},
    stopCamera(){this.stopCameraFn?.();this.stopCameraFn=null;this.cameraActive=false},
    clearSensitive(){this.stopCamera();this.clearPreview();this.records=[];this.total=0;this.people=[];this.staff=[]},
    stop(){this.visible=false;this.generation++;clearInterval(this.timer);this.timer=null;this.busy=false;this.loading=false;this.roleChecking=false;this.clearSensitive()},
    fail(error){this.error=error.message||'操作失败，请重试';if([401,403].includes(error.statusCode)){this.clearSensitive();this.role=null;this.stations=[]}},
    async refreshRole(){const g=this.generation,token=this.ownerToken;if(!token||!this.visible)return;this.roleChecking=true;this.nextRoleCheck=Date.now()+15000;try{const role=await gateApi('/me',{token});if(!this.current(g,token))return;this.role=role;if(!role.canScan){this.clearSensitive();this.stations=[]}else if(!role.canManage){this.people=[];this.staff=[];if(this.tab==='manage')this.tab='scan'}}catch(error){if(this.current(g,token))this.fail(error)}finally{if(this.current(g,token))this.roleChecking=false}},
    async load(){const g=++this.generation,token=getAccessToken();this.ownerToken=token;this.clearSensitive();this.role=null;this.stations=[];this.loading=true;this.busy=false;this.error='';this.notice='';this.roleChecking=false;if(!token||!this.visible){this.loading=false;return}try{await this.refreshRole();if(!this.current(g,token)||!this.role?.canScan)return;const result=await gateApi('/stations?includeInactive=true',{token});if(!this.current(g,token))return;this.stations=result.items||[];this.stationIndex=0;await this.loadTab()}catch(error){if(this.current(g,token))this.fail(error)}finally{if(this.current(g,token))this.loading=false}},
    selectStation(event){this.stopCamera();this.clearPreview();this.stationIndex=Number(event.detail.value)},
    switchTab(tab){if(this.busy)return;this.stopCamera();this.clearPreview();this.tab=tab;this.error='';this.notice='';this.loadTab()},
    async loadTab(){if(this.tab==='records')await this.loadRecords();if(this.tab==='manage'&&this.role?.canManage)await this.loadStaff()},
    async startCamera(){if(this.busy||!this.activeStations[this.stationIndex]||!this.role?.canScan)return;const g=this.generation,token=this.ownerToken;this.stopCamera();this.clearPreview();this.error='';this.notice='';this.cameraActive=true;await this.$nextTick();if(!this.current(g,token)||!this.role?.canScan||!this.cameraActive){this.stopCamera();return}const element=this.$refs.cameraBox?.$el||this.$refs.cameraBox;this.stopCameraFn=startGateCamera(element,payload=>{if(this.current(g,token)){this.stopCamera();this.inspect(payload,'相机扫码')}},error=>{if(this.current(g,token)){this.stopCamera();this.fail(error)}})},
    async chooseImage(){if(this.busy||!this.role?.canScan)return;const g=this.generation,token=this.ownerToken;this.stopCamera();this.clearPreview();this.error='';this.notice='';this.busy=true;try{const payload=await pickGateQrImage();if(this.current(g,token)&&payload){this.busy=false;await this.inspect(payload,'二维码图片识别')}}catch(error){if(this.current(g,token))this.fail(error)}finally{if(this.current(g,token))this.busy=false}},
    async inspect(value,source){if(this.busy||!this.role?.canScan||!this.activeStations[this.stationIndex])return;const g=this.generation,token=this.ownerToken,stationId=this.activeStations[this.stationIndex].id;if(!this.current(g,token))return;this.stopCamera();this.clearPreview();this.notice='';this.error='';this.busy=true;try{const qrPayload=normalizeGatePayload(value),result=await gateApi('/scans/preview',{method:'POST',token,data:{qrPayload,stationId}});if(!this.current(g,token)||!this.role?.canScan)return;if(!gateSeconds(result.expiresAt))throw new Error('待核验信息已过期，请重新扫码');this.preview=result;this.previewSource=source;this.now=Date.now()}catch(error){if(this.current(g,token)){this.clearPreview();this.fail(error)}}finally{if(this.current(g,token))this.busy=false}},
    confirm(decision){if(this.busy||!this.preview||!this.previewRemaining||!this.reason.trim()||!this.role?.canScan)return;const g=this.generation,token=this.ownerToken,previewId=this.preview.previewId,reason=this.reason.trim();if(!this.current(g,token))return;uni.showModal({title:decision==='allow'?'确认放行？':'确认不予放行？',content:`待核验人员：${this.preview.person.name}\n站点：${this.preview.station.name}\n说明：${reason}\n确认后保存核验记录。`,confirmText:decision==='allow'?'确认放行':'确认拒绝',success:async result=>{if(!result.confirm||!this.current(g,token)||this.preview?.previewId!==previewId||!this.role?.canScan||!this.previewRemaining||this.busy)return;this.busy=true;this.error='';try{await gateApi('/scans/confirm',{method:'POST',token,data:{previewId,decision,reason}});if(!this.current(g,token))return;this.clearPreview();this.notice=decision==='allow'?'已确认放行并保存记录。':'已确认不予放行并保存记录。'}catch(error){if(this.current(g,token)){this.clearPreview();this.fail(error)}}finally{if(this.current(g,token))this.busy=false}}})},
    async loadRecords(){if(!this.role?.canScan)return;const g=this.generation,token=this.ownerToken,page=this.page;try{const result=await gateApi('/records?page='+page+'&pageSize=20',{token});if(this.current(g,token)&&this.tab==='records'&&page===this.page){this.records=result.items||[];this.total=result.total||0}}catch(error){if(this.current(g,token))this.fail(error)}},
    async loadStaff(){if(!this.role?.canManage)return;const g=this.generation,token=this.ownerToken;try{const result=await loadAllPages(query=>gateApi('/staff?'+new URLSearchParams(query),{token}),{},()=>this.current(g,token)&&this.role?.canManage);if(this.current(g,token)&&this.role?.canManage)this.staff=result.items||[]}catch(error){if(this.current(g,token))this.fail(error)}},
    async searchPeople(){if(!this.role?.canManage||this.busy)return;const query=this.peopleQuery.trim();if(!query){this.people=[];return}const g=this.generation,token=this.ownerToken;this.busy=true;try{const result=await loadAllPages(params=>gateApi('/people?'+new URLSearchParams(params),{token}),{query},()=>this.current(g,token)&&this.role?.canManage&&query===this.peopleQuery.trim());if(this.current(g,token)&&query===this.peopleQuery.trim()&&this.role?.canManage)this.people=result.items||[]}catch(error){if(this.current(g,token))this.fail(error)}finally{if(this.current(g,token))this.busy=false}},
    askChange(title,content,path,method,data){if(!this.role?.canManage||this.busy)return;const g=this.generation,token=this.ownerToken;if(!this.current(g,token))return;uni.showModal({title,content,success:async result=>{if(!result.confirm||!this.current(g,token)||!this.role?.canManage||(data?.role==='manager'&&!this.role.canGrantManagers)||this.busy)return;this.busy=true;this.error='';try{await gateApi(path,{method,token,data});if(!this.current(g,token))return;this.stationName='';this.stationDescription='';this.people=[];this.notice='已保存配置';const stations=await gateApi('/stations?includeInactive=true',{token});if(!this.current(g,token))return;this.stations=stations.items||[];this.stationIndex=0;await this.loadStaff()}catch(error){if(this.current(g,token))this.fail(error)}finally{if(this.current(g,token))this.busy=false}}})},
    grant(person,role){if(role==='manager'&&!this.role?.canGrantManagers)return;this.askChange('确认授权',`为 ${person.name||person.realName||person.username} 分配${role==='manager'?'保卫负责人':'保安'}权限？`,'/staff','POST',{accountId:person.id,role})},
    revoke(person){if(!person.canRevoke||person.status!=='active')return;this.askChange('撤销核验权限',`撤销 ${person.person?.name||person.person?.username} 的核验工作权限？`,'/staff/'+person.id,'DELETE')},
    addStation(){if(!this.stationName.trim())return;this.askChange('新增核验站点',`新增站点“${this.stationName.trim()}”？`,'/stations','POST',{name:this.stationName.trim(),description:this.stationDescription.trim()})},
    toggleStation(station){const status=station.status==='active'?'disabled':'active';this.askChange(status==='active'?'启用核验站点':'停用核验站点',`确认${status==='active'?'启用':'停用'}“${station.name}”？`,'/stations/'+station.id,'PATCH',{status,expectedRevision:station.revision})}
  }
}
</script>

<style scoped>
.gate-page{max-width:1040px;margin:auto}.gate-hero{padding:28rpx 8rpx}.gate-eyebrow,.gate-title,.gate-description,.gate-policy,.gate-heading,.gate-muted{display:block}.gate-eyebrow{color:#9c7e44;font-size:18rpx;letter-spacing:3rpx}.gate-title{margin-top:10rpx;font-size:38rpx;font-weight:750;color:#12345d}.gate-description{margin-top:12rpx;font-size:24rpx;color:#5e728a}.gate-policy{margin-top:16rpx;font-size:21rpx;color:#858f9e;line-height:1.7}.gate-box{padding:28rpx;margin:22rpx 0}.gate-heading{font-size:28rpx;font-weight:700;color:#1b385a}.gate-muted{margin-top:10rpx;color:#7d8a9c;font-size:22rpx;line-height:1.7;overflow-wrap:anywhere}.gate-spaced{margin-top:32rpx}.gate-tabs,.gate-actions,.gate-inline-actions,.gate-pagination,.gate-section-head{display:flex;align-items:center;gap:14rpx;flex-wrap:wrap}.gate-tabs{margin-top:12rpx}.gate-tabs button{margin:0;flex:1;padding:15rpx 12rpx;font-size:24rpx;color:#748399;background:#e9eff6;border-radius:16rpx;line-height:1.6;white-space:nowrap}.gate-tabs button.active{background:#033481;color:white}.gate-select{margin-top:18rpx;display:flex;justify-content:space-between;padding:22rpx;border:1rpx solid #dbe3ed;border-radius:14rpx;color:#315476;font-size:24rpx}.gate-actions{margin-top:22rpx}.gate-actions>button{flex:1;min-width:200rpx;margin:0}.gate-input{box-sizing:border-box;width:100%;height:86rpx;padding:20rpx;margin-top:18rpx;font-size:24rpx;border:1rpx solid #dce4ef;border-radius:14rpx;background:#f8fafc}.gate-input:disabled{opacity:.6}.gate-actions>.gate-input{flex:1;min-width:230rpx;margin:0}.gate-manual{margin-top:30rpx;padding-top:20rpx;border-top:1rpx solid #e4ebf3}.gate-code-input{height:130rpx;word-break:break-all}.gate-camera{margin-top:20rpx}.gate-person{display:flex;flex-direction:column;gap:13rpx;margin:20rpx 0;padding:26rpx;border-radius:18rpx;background:#f0f5fb;font-size:24rpx;color:#3d5b79;overflow-wrap:anywhere}.gate-person-name{font-size:40rpx;font-weight:750;color:#153b67}.gate-preview textarea{height:160rpx}.gate-deny{background:#f7e8e6;color:#a4433d;font-size:25rpx;border-radius:18rpx}.gate-link{background:transparent;color:#426a96;font-size:23rpx;margin:18rpx auto 0}.gate-link::after{border:0}.gate-error,.gate-notice{margin:18rpx 0;padding:20rpx;border-radius:14rpx;background:#fceeee;color:#a23b3b;font-size:24rpx;line-height:1.7}.gate-notice{background:#eaf5ed;color:#26704c}.gate-list-row{display:flex;align-items:center;justify-content:space-between;gap:14rpx;padding:24rpx 0;border-bottom:1rpx solid #e9eef5}.gate-list-row>view:first-child{flex:1;min-width:0}.gate-row-title{font-size:25rpx;color:#244562;font-weight:600;overflow-wrap:anywhere}.gate-list-row button,.gate-pagination button{font-size:22rpx;color:#315d87;background:#edf3fa;padding:10rpx 18rpx;margin:0;line-height:1.8}.gate-inline-actions{justify-content:flex-end}.gate-pagination{justify-content:space-between;margin-top:26rpx;font-size:22rpx;color:#5c6d83}.gate-section-head{justify-content:space-between}.gate-section-head button{margin:0}.gate-box>.primary-button,.gate-box>.secondary-button,.gate-manual button{margin-top:20rpx}@media(min-width:900px){.gate-box{padding:30px}.gate-title{font-size:32px}.gate-heading{font-size:22px}.gate-muted{font-size:15px}.gate-actions>button{max-width:350px}.gate-list-row{padding:18px 0}}@media(max-width:380px){.gate-list-row{align-items:flex-start;flex-direction:column}.gate-tabs button{font-size:22rpx}}
</style>
